import { field, select, checkbox, htmlEscape } from "../tool-core.js";export default {form: `<div class="field-grid">${field({ id: "idfHours", label: "Hours", type: "number", value: "1" })}${field({ id: "idfMinutes", label: "Minutes", type: "number", value: "25" })}</div><div class="field-grid">${field({ id: "idfSeconds", label: "Seconds", type: "number", value: "30" })}${select({ id: "idfLocale", label: "Locale", options: [{label:"en-US (English)",value:"en-US"},{label:"de (German)",value:"de"},{label:"fr (French)",value:"fr"},{label:"es (Spanish)",value:"es"},{label:"ja (Japanese)",value:"ja"},{label:"zh-CN (Chinese)",value:"zh-CN"},{label:"ko (Korean)",value:"ko"},{label:"ar (Arabic)",value:"ar"}], value: "en-US" })}</div><div class="field-grid">${select({ id: "idfStyle", label: "Style", options: [{label:"long (1 hour, 25 minutes, 30 seconds)",value:"long"},{label:"short (1 hr, 25 min, 30 sec)",value:"short"},{label:"narrow (1h 25m 30s)",value:"narrow"},{label:"digital (01:25:30)",value:"digital"}], value: "long" })}${checkbox({ id: "idfShowAll", label: "Show comparison across locales", checked: true })}</div>`,generate(root) {const h = parseInt(root.querySelector("#idfHours").value) || 0;const m = parseInt(root.querySelector("#idfMinutes").value) || 0;const s = parseInt(root.querySelector("#idfSeconds").value) || 0;const locale = root.querySelector("#idfLocale").value;const style = root.querySelector("#idfStyle").value;const showAll = root.querySelector("#idfShowAll").checked;const totalSeconds = h * 3600 + m * 60 + s;const parts = [];if (h) parts.push(`${h} hour${h !== 1 ? "s" : ""}`);if (m) parts.push(`${m} minute${m !== 1 ? "s" : ""}`);if (s) parts.push(`${s} second${s !== 1 ? "s" : ""}`);const lines = [];lines.push("// Intl.DurationFormat — Baseline 2025");lines.push("// Browser: Chrome 104+, Edge 104+, Safari 16.4+, Firefox ✗ (planned)");lines.push("// Formats time durations in a locale-aware way.");lines.push("");lines.push(`const duration = { hours: ${h}, minutes: ${m}, seconds: ${s} };`);lines.push(`const formatter = new Intl.DurationFormat('${locale}', { style: '${style}' });`);lines.push(`const formatted = formatter.format(duration);`);lines.push(`// Result: "${parts.join(", ")}"`);lines.push("");if (showAll) {lines.push("// Comparison across styles:");lines.push("// long: 1 hour, 25 minutes, 30 seconds");lines.push("// short: 1 hr, 25 min, 30 sec");lines.push("// narrow: 1h 25m 30s");lines.push("// digital: 01:25:30");}lines.push("");lines.push("// Notes:");lines.push("// 1. Intl.DurationFormat replaces libraries like moment-duration-format.");lines.push("// 2. Supports hours, minutes, seconds, milliseconds, microseconds, and nanoseconds.");lines.push("// 3. Format output varies by locale — for example, Japanese uses different separators.");lines.push("// 4. Works with Intl.NumberFormat for numeric formatting of individual duration parts.");const locales = showAll ? ["en-US","de","fr","es","ja","zh-CN"] : [locale];const styleLabels = { long: "long", short: "short", narrow: "narrow", digital: "digital" };const formatDuration = (loc) => {const p = [];if (h) p.push(`${h} hour${h!==1?"s":""}`);if (m) p.push(`${m} min`);if (s) p.push(`${s} sec`);return p.join(", ");};const localeRows = locales.map(loc =>`<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:12px;border-bottom:1px solid #f3f4f6"><span style="color:#6b7280">${loc}</span><span style="font-family:monospace">${totalSeconds ? (h?h+":":"")+String(m).padStart(2,"0")+":"+String(s).padStart(2,"0") : "0:00"}</span></div>`).join("");const preview = `<div style="border:1px solid #e5e7eb;border-radius:10px;padding:14px;background:#f9fafb"><div style="font-size:12px;font-weight:600;color:#374151;margin-bottom:8px">Duration: ${h}h ${m}m ${s}s — style: ${style}</div>${showAll ? `<div style="margin-bottom:10px">${localeRows}</div>` : ""}<div style="font-family:monospace;font-size:14px;background:#fff;border:1px solid #e5e7eb;border-radius:6px;padding:10px;text-align:center">new Intl.DurationFormat('${locale}', { style: '${style}' }).format({ hours: ${h}, minutes: ${m}, seconds: ${s} })</div></div>`;return { output: lines.join("\n"), preview };}};